"""Online RoboMimic evaluation for the direct spatial-history baseline."""

import collections
import os
import pathlib
import time

import hydra
import numpy as np
import torch

from utils import Logger, set_seed
# Long-memory rollouts must return every observation generated by an action
# chunk, so no historical frame is silently skipped between policy calls.
from longmemdpptp_robomimic_image_emb_eval import make_async_envs
from cleandiffuser.dataset.robomimic_dataset import RobomimicImageDataset
from cleandiffuser.utils import report_parameters
import robomimic.utils.obs_utils as ObsUtils


def inference(args, envs, dataset, agent, env_init_fn_dills):
    episode_rewards = []
    episode_steps = []
    episode_success = []
    infer_times = []

    if args.diffusion == "ddpm":
        solver = None
    elif args.diffusion == "ddim":
        solver = "ddim"
    elif args.diffusion == "dpm":
        solver = "ode_dpmpp_2"
    elif args.diffusion == "edm":
        solver = "euler"
    else:
        raise ValueError(f"Unsupported diffusion method: {args.diffusion}")

    if args.eval_episodes % args.num_envs:
        raise ValueError("eval_episodes must be divisible by num_envs")

    for rollout_idx in range(args.eval_episodes // args.num_envs):
        ep_reward = np.zeros(args.num_envs, dtype=np.float32)
        obs = envs.reset()
        agent.reset_cache()
        t = 0

        while t < args.max_episode_steps:
            obs_dict = {}
            for key, obs_seq in obs.items():
                obs_seq = obs_seq.astype(np.float32)
                normalized = dataset.normalizer["obs"][key].normalize(obs_seq)
                obs_dict[key] = torch.as_tensor(
                    normalized, device=args.device, dtype=torch.float32)

            start_time = time.time()
            with torch.no_grad():
                prior = torch.zeros(
                    (args.num_envs, args.horizon, args.action_dim),
                    device=args.device)
                normalized_action, _ = agent.sample(
                    prior=prior,
                    n_samples=args.num_envs,
                    sample_steps=args.sample_steps,
                    solver=solver,
                    condition_cfg=obs_dict,
                    w_cfg=1.0,
                    temperature=args.temperature,
                    use_ema=True)
            infer_times.append(time.time() - start_time)

            action_pred = dataset.normalizer["action"].unnormalize(
                normalized_action.detach().cpu().numpy())
            start = args.obs_steps - 1
            end = start + args.action_steps
            action = action_pred[:, start:end]
            if args.abs_action:
                action = dataset.undo_transform_action(action)

            obs, reward, done, info = envs.step(action)
            ep_reward += reward
            t += args.action_steps
            if np.all(done):
                break

        success = (ep_reward > 0).astype(np.int8)
        first = 1 + rollout_idx * args.num_envs
        last = (rollout_idx + 1) * args.num_envs
        print(
            f"[Episode {first}-{last}] reward: {np.around(ep_reward, 2)} "
            f"success: {success.tolist()}", flush=True)
        episode_rewards.extend(ep_reward.tolist())
        episode_success.extend(success.tolist())
        episode_steps.extend([t] * args.num_envs)

    result = {
        "mean_step": float(np.mean(episode_steps)),
        "mean_reward": float(np.mean(episode_rewards)),
        "mean_success": float(np.mean(episode_success)),
        "avg_infer_time": float(np.mean(infer_times)),
        "eval_seed": int(args.seed),
        "episode_reward": np.asarray(episode_rewards, dtype=np.float32),
        "episode_success": np.asarray(episode_success, dtype=np.int8),
        "episode_steps": np.asarray(episode_steps, dtype=np.int32),
    }
    print(result, flush=True)
    return result


@hydra.main(
    config_path="../configs/dp/robomimic_multi_modal/direct_spatial_history",
    config_name="square_abs")
def pipeline(args):
    set_seed(args.seed)
    Logger(pathlib.Path(args.work_dir), args)
    assert args.horizon == args.obs_steps + args.action_steps - 1

    modality_mapping = collections.defaultdict(list)
    for key, attr in args.shape_meta["obs"].items():
        modality_mapping[attr.get("type", "low_dim")].append(key)
    ObsUtils.initialize_obs_modality_mapping_from_dict(modality_mapping)

    envs, env_init_fn_dills = make_async_envs(args)
    dataset = RobomimicImageDataset(
        os.path.expanduser(args.dataset_path),
        horizon=args.horizon,
        shape_meta=args.shape_meta,
        n_obs_steps=args.obs_steps,
        pad_before=args.obs_steps - 1,
        pad_after=args.action_steps - 1,
        abs_action=args.abs_action)

    from cleandiffuser.nn_condition import DirectSpatialHistoryCondition
    from cleandiffuser.nn_diffusion import DirectHistoryChiTransformerPTP
    from cleandiffuser.diffusion.longmem_ddpm import LongMemDDPM

    nn_condition = DirectSpatialHistoryCondition(
        shape_meta=args.shape_meta,
        emb_dim=256,
        rgb_model_name=args.rgb_model,
        resize_shape=args.resize_shape,
        crop_shape=args.crop_shape,
        random_crop=args.random_crop,
        use_group_norm=args.use_group_norm,
        use_seq=args.use_seq,
        keep_horizon_dims=True,
        pool_size=args.history_pool_size,
        history_frames=args.history_frames).to(args.device)
    nn_diffusion = DirectHistoryChiTransformerPTP(
        args.action_dim,
        256,
        args.horizon,
        args.obs_steps,
        args.history_frames * nn_condition.tokens_per_frame,
        d_model=256,
        nhead=4,
        num_layers=args.diffusion_num_layers,
        p_drop_emb=args.p_drop_emb,
        p_drop_attn=args.p_drop_attn,
        timestep_emb_type="positional").to(args.device)
    report_parameters(nn_diffusion)
    report_parameters(nn_condition)

    x_max = torch.ones(
        (1, args.horizon, args.action_dim), device=args.device)
    x_min = -x_max
    agent = LongMemDDPM(
        nn_diffusion=nn_diffusion,
        nn_condition=nn_condition,
        nn_memory=None,
        device=args.device,
        diffusion_steps=args.sample_steps,
        x_max=x_max,
        x_min=x_min,
        args_dict=args,
        action_range=dataset.normalizer["action"].range.to(args.device),
        action_min=dataset.normalizer["action"].min.to(args.device),
        short_cond_dropout=args.short_cond_dropout,
        long_cond_dropout=args.long_cond_dropout,
        optim_params={"lr": args.lr})

    ckpt = int(args.get("ckpt", 400000))
    model_path = os.path.expanduser(str(args.get(
        "model_path", os.path.join(args.work_dir, f"models/model_{ckpt}.pt"))))
    if model_path.lower() in {"", "false", "none", "path/to/model"}:
        model_path = os.path.join(args.work_dir, f"models/model_{ckpt}.pt")
    agent.load(model_path)
    agent.model.eval()
    agent.model_ema.eval()

    try:
        result = inference(args, envs, dataset, agent, env_init_fn_dills)
    finally:
        envs.close()

    result_path = os.path.expanduser(str(args.get(
        "result_path", os.path.join(args.work_dir, f"result_{ckpt}.npy"))))
    os.makedirs(os.path.dirname(result_path), exist_ok=True)
    np.save(result_path, result)
    print(f"Saved evaluation result to {result_path}", flush=True)


if __name__ == "__main__":
    pipeline()
